/**
 * @method
 * @name calFlowPosblShrs
 * @description cal Flow Posbl Shrs 처리
 * @returns {void}
 * @hidden N
 */
scwin.calFlowPosblShrs = function () {
    const trdObjStkTpCdItem = $c.util.getComponent('ipt_trdObjStkTpCd');
    let isuShrs = 0;
    let flowPosblShrs = 0;
    let flowPosblShrsIndex = 0;
    for (let i = 0; i < trdObjStkTpCdItem.length; i++) {
        const trdObjStkTpCd = $c.util.getComponent('ipt_trdObjStkTpCd')[i].value;
        isuShrs = $c.util.getComponent('isuShrs')[i].value.replace(/^\$|,/g, "") + "";
        if (isuShrs === '') {
            isuShrs = '0';
        }
        if (trdObjStkTpCd === '6') {
            flowPosblShrsIndex = i;
            continue;
        }
        if (trdObjStkTpCd === '1') {
            flowPosblShrs += parseInt(isuShrs);
        } else {
            flowPosblShrs -= parseInt(isuShrs);
        }
    }
    if (flowPosblShrs === 0) {
        $c.util.getComponent('flowPosblShrs')[flowPosblShrsIndex].value = flowPosblShrs;
    } else {
        $c.util.getComponent('flowPosblShrs')[flowPosblShrsIndex].value = $c.num.formatNumber(flowPosblShrs);
    }
};

function deleteRow(obj) {
    const table = obj.parentNode.parentNode.parentNode.parentNode;
    table.deleteRow(obj.parentNode.parentNode.rowIndex);
}

