 */
scwin.openNewPrtdepoWin = async function (bzProcsNo, prtdepoId) {
    const prtdepoWin = {};
    prtdepoWin.calcelYn = 'Y';
    const url = "/ui/jsp/JLDFIL55220.xml?method=selectDepo&bzProcsNo=" + bzProcsNo + "&prtdepoId=" + prtdepoId + "&isurCd=" + "" + dma_pageContext.get("isurCd") + "";
    const style = "dialogWidth:730px;dialogHeight:480px;scroll:no;resize:no";
    Object.assign(prtdepoWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, prtdepoWin)) || {});
    if (prtdepoWin.calcelYn === 'N') {
        const frm = $c.util.getComponent('ListShrsForm');
        $c.util.getComponent('dma_registReq').set('method', 'searchListShrs');
        await scwin.tx_fn_openNewPrtdepoWin('listShrs.do');
    }
};

