/**
 * @method
 * @name openStockDutyWin
 * @description open Stock Duty Win 처리
 * @param {*} bzProcsNo bzProcsNo
 * @param {String} prtdepoId prtdepoId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openStockDutyWin = async function (bzProcsNo, prtdepoId) {
    const stockDutyWin = {};
    stockDutyWin.calcelYn = 'Y';
    const url = "/ui/jsp/JLDFIL55230.xml?method=selectStockDuty&bzProcsNo=" + bzProcsNo + "&prtdepoId=" + prtdepoId + "&isurCd=" + "" + dma_pageContext.get("isurCd") + "";
    const style = "dialogWidth:730px;dialogHeight:430px;scroll:no;resize:no";
    Object.assign(stockDutyWin, (await $c.win.openPopup(url, { type: 'pageFramePopup', modal: true }, stockDutyWin)) || {});
    if (stockDutyWin.calcelYn === 'N') {
        const frm = $c.util.getComponent('ListShrsForm');
        $c.util.getComponent('dma_registReq').set('method', 'searchListShrs');
        await scwin.tx_fn_openStockDutyWin('listShrs.do');
    }
};

/**
 * @method
 * @name specialWord
 * @description special Word 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.specialWord = async function () {
    let nm = $c.util.getComponent('nm').getValue();
    if (nm.indexOf("\\") !== -1) {
        nm = nm.replace(/\\/g, "");
        $c.util.getComponent('nm').setValue(nm);
        await $c.win.alert("\\는 입력할 수 없습니다");
    }
    if (nm.indexOf("\"") !== -1) {
        nm = nm.replace(/"/g, "");
    $c.util.getComponent('nm').setValue(nm);
    await $c.win.alert("\"는 입력할 수 없습니다");
    }
};

